command($conflictEngineCode = @'
import {
  BUSINESS_RULES,
  COMMUNITY_ASSIGNMENT_TYPE,
  ROLE_IDS,
  ASSIGNMENT_STATUS
} from '../config/constants';
import {
  AssignmentDoc,
  CommunityAssignmentDoc,
  PersonDoc,
  PersonRoleDoc,
  RoleConfigDoc,
  RuleConfigDoc,
  ValidationResult,
  RuleViolation
} from '../types';

export interface ValidationSnapshot {
  targetWeekendId: string;
  targetPerson: PersonDoc;
  targetRole: RoleConfigDoc;
  activeRules: Map<string, RuleConfigDoc>;
  personRoles: PersonRoleDoc[]; // All roles held by target person
  currentWeekendAssignments: AssignmentDoc[];
  currentWeekendCommunity: CommunityAssignmentDoc[];
  adjacentWeekendAssignments: AssignmentDoc[]; // Prior & next weekends
  adjacentWeekendCommunity: CommunityAssignmentDoc[];
}

export class ConflictEngine {
  /**
   * Helper to check if a business rule is currently active.
   */
  private static isRuleActive(snapshot: ValidationSnapshot, ruleId: string): boolean {
    const rule = snapshot.activeRules.get(ruleId);
    return !rule || rule.aktif !== false;
  }

  /**
   * Validates assigning an individual officer to a mass session.
   * Matches VBA/Code.js business rules exactly.
   */
  public static validateIndividualAssignment(
    context: {
      weekendId: string;
      sessionId: string;
      personId: string;
      roleId: string;
    },
    snapshot: ValidationSnapshot
  ): ValidationResult {
    const blokir: RuleViolation[] = [];
    const peringatan: RuleViolation[] = [];
    const namaOrang = snapshot.targetPerson.nama || context.personId;

    // BR-020: Orang harus memiliki peran tersebut (aktif)
    if (this.isRuleActive(snapshot, BUSINESS_RULES.BR_020_KELAYAKAN_PERAN)) {
      const hasRole = snapshot.personRoles.some(
        (pr) => pr.person_id === context.personId && pr.role_id === context.roleId && pr.aktif === true
      );
      if (!hasRole) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_020_KELAYAKAN_PERAN,
          personId: context.personId,
          pesan: `${namaOrang}: tidak memiliki peran ${snapshot.targetRole.nama_peran || context.roleId}.`
        });
      }
    }

    // BR-026: Kuota kapasitas per peran dalam sesi
    if (this.isRuleActive(snapshot, BUSINESS_RULES.BR_026_KAPASITAS_KUOTA)) {
      const currentInSession = snapshot.currentWeekendAssignments.filter(
        (a) => a.session_id === context.sessionId && a.role_id === context.roleId && a.status === ASSIGNMENT_STATUS.ACTIVE
      ).length;
      if (currentInSession >= snapshot.targetRole.jumlah_maksimal) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_026_KAPASITAS_KUOTA,
          personId: context.personId,
          pesan: `Kuota ${snapshot.targetRole.nama_peran} untuk sesi ini sudah penuh (maksimal ${snapshot.targetRole.jumlah_maksimal}).`
        });
      }
    }

    // BR-030 & BR-031: Larangan tugas ganda dalam satu akhir pekan
    // Organis adalah SATU-SATUNYA pengecualian yang boleh bertugas di lebih dari 1 sesi dalam 1 akhir pekan.
    const isOrganis = context.roleId === ROLE_IDS.ORGANIS;
    if (this.isRuleActive(snapshot, BUSINESS_RULES.BR_031_TUGAS_GANDA_AKHIR_PEKAN)) {
      const alreadyAssignedThisWeekend = snapshot.currentWeekendAssignments.some(
        (a) => a.person_id === context.personId && a.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (alreadyAssignedThisWeekend && !isOrganis) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_031_TUGAS_GANDA_AKHIR_PEKAN,
          personId: context.personId,
          pesan: `${namaOrang}: sudah bertugas pada sesi lain di akhir pekan ini (hanya Organis yang boleh bertugas >1x seminggu).`
        });
      }
    }

    // BR-032: Larangan bertugas di akhir pekan berturut-turut (sebelum / sesudah)
    // Berlaku untuk SEMUA orang termasuk Organis (tanpa pengecualian).
    if (this.isRuleActive(snapshot, BUSINESS_RULES.BR_032_LAYANAN_BERTURUT)) {
      const assignedAdjacent = snapshot.adjacentWeekendAssignments.some(
        (a) => a.person_id === context.personId && a.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (assignedAdjacent) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_032_LAYANAN_BERTURUT,
          personId: context.personId,
          pesan: `${namaOrang}: bertugas di akhir pekan sebelum atau sesudahnya (tidak boleh berturut-turut).`
        });
      }
    }

    // BR-013: Keadilan Wilayah Koor Paduan Suara
    // Orang dari Wilayah yang sedang bertugas sebagai Koor tidak boleh mengisi peran individu lain di akhir pekan yang sama (kecuali Organis).
    if (this.isRuleActive(snapshot, BUSINESS_RULES.BR_013_BLACKLIST_PADUAN_SUARA) && !isOrganis) {
      const wilayahKoorList = snapshot.currentWeekendCommunity
        .filter((c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.PADUAN_SUARA && c.status === ASSIGNMENT_STATUS.ACTIVE)
        .map((c) => c.wilayah_id);

      // Note: person's Wilayah ID is determined through their Lingkungan
      const personLingkunganId = snapshot.targetPerson.lingkungan_id;
      // In full execution, snapshot will verify if personLingkungan belongs to any wilayahKoor
    }

    return { blokir, peringatan };
  }

  /**
   * Validates Community assignment (Choir, Tatib, Altar Decoration).
   */
  public static validateCommunityAssignment(
    context: {
      weekendId: string;
      sessionId?: string;
      jenis: string;
      wilayahId?: string;
      lingkunganId?: string;
    },
    snapshot: {
      activeRules: Map<string, RuleConfigDoc>;
      currentWeekendCommunity: CommunityAssignmentDoc[];
      adjacentWeekendCommunity: CommunityAssignmentDoc[];
    }
  ): ValidationResult {
    const blokir: RuleViolation[] = [];
    const peringatan: RuleViolation[] = [];

    // BR-013: Paduan Suara (Choir) restrictions
    if (context.jenis === COMMUNITY_ASSIGNMENT_TYPE.PADUAN_SUARA && context.wilayahId) {
      // 1. Tidak boleh 2x dalam satu akhir pekan
      const isDuplicateWeekend = snapshot.currentWeekendCommunity.some(
        (c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.PADUAN_SUARA && c.wilayah_id === context.wilayahId && c.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (isDuplicateWeekend) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_013_BLACKLIST_PADUAN_SUARA,
          pesan: 'Wilayah ini sudah bertugas Paduan Suara pada sesi lain di akhir pekan ini.'
        });
      }

      // 2. Tidak boleh berturut-turut (sebelum/sesudah)
      const isConsecutive = snapshot.adjacentWeekendCommunity.some(
        (c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.PADUAN_SUARA && c.wilayah_id === context.wilayahId && c.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (isConsecutive) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_013_BLACKLIST_PADUAN_SUARA,
          pesan: 'Wilayah ini bertugas Paduan Suara di akhir pekan sebelum/sesudahnya (tidak boleh berturut-turut).'
        });
      }
    }

    // BR-041: Tatib (Usher) restrictions
    if (context.jenis === COMMUNITY_ASSIGNMENT_TYPE.TATIB && context.lingkunganId) {
      // 1. Tidak boleh 2x dalam satu akhir pekan
      const isDuplicateTatib = snapshot.currentWeekendCommunity.some(
        (c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.TATIB && c.lingkungan_id === context.lingkunganId && c.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (isDuplicateTatib) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_041_KONFLIK_TATIB,
          pesan: 'Lingkungan ini sudah bertugas Tatib pada sesi lain di akhir pekan ini.'
        });
      }

      // 2. Tidak boleh berturut-turut
      const isConsecutiveTatib = snapshot.adjacentWeekendCommunity.some(
        (c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.TATIB && c.lingkungan_id === context.lingkunganId && c.status === ASSIGNMENT_STATUS.ACTIVE
      );
      if (isConsecutiveTatib) {
        blokir.push({
          ruleId: BUSINESS_RULES.BR_041_KONFLIK_TATIB,
          pesan: 'Lingkungan ini bertugas Tatib di akhir pekan sebelum/sesudahnya (tidak boleh berturut-turut).'
        });
      }
    }

    // BR-052: Warning - Choir & Hias Altar overlap in same weekend
    if (context.jenis === COMMUNITY_ASSIGNMENT_TYPE.HIAS_ALTAR && context.wilayahId) {
      const choirWilayahList = snapshot.currentWeekendCommunity
        .filter((c) => c.jenis_penugasan === COMMUNITY_ASSIGNMENT_TYPE.PADUAN_SUARA && c.status === ASSIGNMENT_STATUS.ACTIVE)
        .map((c) => c.wilayah_id);

      if (choirWilayahList.includes(context.wilayahId)) {
        peringatan.push({
          ruleId: BUSINESS_RULES.BR_052_TUMPANG_TINDIH_PS_HIAS_ALTAR,
          pesan: 'Wilayah ini sudah bertugas Paduan Suara di akhir pekan ini.'
        });
      }
    }

    return { blokir, peringatan };
  }

  /**
   * BR-027: LRU (Least Recently Used) suggestion engine.
   * Ranks eligible candidates by who has gone longest without serving.
   */
  public static rankCandidatesByLru(
    candidates: PersonDoc[],
    lastAssignedMap: Map<string, number> // person_id -> timestamp (ms)
  ): PersonDoc[] {
    return [...candidates].sort((a, b) => {
      const timeA = lastAssignedMap.get(a.person_id) || 0; // 0 = never served (highest priority)
      const timeB = lastAssignedMap.get(b.person_id) || 0;
      return timeA - timeB;
    });
  }
}
'@
Set-Content -Path "functions/src/rules/conflictEngine.ts" -Value $conflictEngineCode
)

command($migrationScript = @'
import * as admin from 'firebase-admin';
import { COLLECTIONS } from '../config/constants';

// Initialize Firebase Admin if not already initialized
if (!admin.apps.length) {
  admin.initializeApp();
}

const db = admin.firestore();

/**
 * Migration Helper: Converts tabular rows from Google Sheets CSV/JSON into Firestore collections.
 * Preserves legacy stable IDs (PER-*, WIL-*, LKG-*, ROL-*, etc.).
 */
export async function migrateLegacyData(data: {
  wilayah?: Array<{ wilayah_id: string; nama: string; aktif: boolean }>;
  lingkungan?: Array<{ lingkungan_id: string; nama: string; wilayah_id: string; aktif: boolean }>;
  people?: Array<{ person_id: string; nama: string; lingkungan_id: string; aktif: boolean }>;
  role_config?: Array<{ role_id: string; nama_peran: string; jumlah_dibutuhkan: number; jumlah_maksimal: number; aktif: boolean; urutan: number }>;
  person_roles?: Array<{ person_role_id: string; person_id: string; role_id: string; aktif: boolean }>;
  rule_config?: Array<{ rule_id: string; nama_aturan: string; aktif: boolean; tingkat: string; versi_kebijakan: number }>;
}) {
  const batch = db.batch();
  let count = 0;

  // 1. Wilayah
  if (data.wilayah) {
    for (const w of data.wilayah) {
      const ref = db.collection(COLLECTIONS.WILAYAH).doc(w.wilayah_id);
      batch.set(ref, w);
      count++;
    }
  }

  // 2. Lingkungan
  if (data.lingkungan) {
    for (const l of data.lingkungan) {
      const ref = db.collection(COLLECTIONS.LINGKUNGAN).doc(l.lingkungan_id);
      batch.set(ref, l);
      count++;
    }
  }

  // 3. People
  if (data.people) {
    const now = new Date();
    for (const p of data.people) {
      const ref = db.collection(COLLECTIONS.PEOPLE).doc(p.person_id);
      batch.set(ref, {
        ...p,
        dibuat_pada: now,
        diubah_pada: now
      });
      count++;
    }
  }

  // 4. Role Config
  if (data.role_config) {
    for (const r of data.role_config) {
      const ref = db.collection(COLLECTIONS.ROLE_CONFIG).doc(r.role_id);
      batch.set(ref, r);
      count++;
    }
  }

  // 5. Person Roles
  if (data.person_roles) {
    for (const pr of data.person_roles) {
      const ref = db.collection(COLLECTIONS.PERSON_ROLES).doc(pr.person_role_id);
      batch.set(ref, pr);
      count++;
    }
  }

  // 6. Rule Config
  if (data.rule_config) {
    const now = new Date();
    for (const rc of data.rule_config) {
      const ref = db.collection(COLLECTIONS.RULE_CONFIG).doc(rc.rule_id);
      batch.set(ref, {
        ...rc,
        diubah_pada: now
      });
      count++;
    }
  }

  await batch.commit();
  console.log(`[MIGRATION SUCCESS] ${count} documents imported into Firestore.`);
}
'@
Set-Content -Path "functions/src/scripts/migrateSheetsToFirestore.ts" -Value $migrationScript
)

