$authContextCode = @'
import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import {
  signInWithPopup,
  signOut as firebaseSignOut,
  onAuthStateChanged,
  type User as FirebaseUser
} from 'firebase/auth';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { auth, googleProvider, db } from '../config/firebase';
import type { User, UserRole } from '../types';

interface AuthContextType {
  user: User | null;
  firebaseUser: FirebaseUser | null;
  loading: boolean;
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
  const [user, setUser] = useState<User | null>({
    // Default fallback mock user for initial offline/preview mode
    email: 'admin@paroki.org',
    role: 'ADMIN',
    displayName: 'Admin Paroki'
  });
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      setFirebaseUser(fbUser);
      if (fbUser && fbUser.email) {
        try {
          // Fetch user role from Firestore 'users' collection
          const userDocRef = doc(db, 'users', fbUser.uid);
          const userSnap = await getDoc(userDocRef);

          let role: UserRole = 'VIEWER';
          if (userSnap.exists()) {
            role = (userSnap.data()?.role as UserRole) || 'VIEWER';
          } else {
            // First time login - default to VIEWER (fail-closed)
            await setDoc(userDocRef, {
              uid: fbUser.uid,
              email: fbUser.email,
              display_name: fbUser.displayName || fbUser.email,
              role: 'VIEWER',
              created_at: new Date(),
              updated_at: new Date()
            });
          }

          setUser({
            email: fbUser.email,
            role,
            displayName: fbUser.displayName || fbUser.email
          });
        } catch (error) {
          console.warn('[AUTH] Could not fetch user role from Firestore, using default:', error);
          setUser({
            email: fbUser.email,
            role: 'VIEWER',
            displayName: fbUser.displayName || fbUser.email
          });
        }
      } else {
        // In local demo mode if not signed in, retain demo profile
        setUser({
          email: 'admin@paroki.org',
          role: 'ADMIN',
          displayName: 'Admin Paroki (Demo)'
        });
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error('[AUTH ERROR] Google Sign-In failed:', error);
      throw error;
    }
  };

  const signOut = async () => {
    try {
      await firebaseSignOut(auth);
    } catch (error) {
      console.error('[AUTH ERROR] Sign-out failed:', error);
      throw error;
    }
  };

  return (
    <AuthContext.Provider value={{ user, firebaseUser, loading, signInWithGoogle, signOut }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
'@
Set-Content -Path "frontend/src/context/AuthContext.tsx" -Value $authContextCode

$apiServiceCode = @'
import { httpsCallable } from 'firebase/functions';
import {
  collection,
  doc,
  onSnapshot,
  query,
  where,
  orderBy
} from 'firebase/firestore';
import { db, functions } from '../config/firebase';
import type { Weekend, Session, Assignment, CommunityAssignment, Person } from '../types';

export interface AssignParams {
  weekendId: string;
  sessionId: string;
  roleId: string;
  personIds: string[];
  expectedRevision: number;
  overrideReason?: string;
}

/**
 * Call the transactional Cloud Function to assign individuals.
 */
export async function assignIndividualApi(params: AssignParams) {
  const assignFn = httpsCallable<AssignParams, { success: boolean; message?: string; assignments?: Assignment[] }>(
    functions,
    'assignIndividual'
  );
  const result = await assignFn(params);
  return result.data;
}

/**
 * Call the finalize weekend Cloud Function (Admin only).
 */
export async function finalizeWeekendApi(params: { weekendId: string; expectedRevision: number }) {
  const finalizeFn = httpsCallable<{ weekendId: string; expectedRevision: number }, { success: boolean; message?: string }>(
    functions,
    'finalizeWeekend'
  );
  const result = await finalizeFn(params);
  return result.data;
}

/**
 * Real-time listener for Weekend schedule details.
 */
export function subscribeToWeekend(
  weekendId: string,
  onUpdate: (data: {
    weekend: Weekend | null;
    sessions: Session[];
    assignments: Assignment[];
    communityAssignments: CommunityAssignment[];
  }) => void
) {
  const weekendRef = doc(db, 'weekends', weekendId);
  const sessionsQuery = query(collection(db, 'weekends', weekendId, 'sessions'));
  const assignmentsQuery = query(
    collection(db, 'weekends', weekendId, 'assignments'),
    where('status', '==', 'ACTIVE')
  );
  const communityQuery = query(
    collection(db, 'weekends', weekendId, 'community_assignments'),
    where('status', '==', 'ACTIVE')
  );

  let weekendData: Weekend | null = null;
  let sessionsData: Session[] = [];
  let assignmentsData: Assignment[] = [];
  let communityData: CommunityAssignment[] = [];

  const unsubWeekend = onSnapshot(weekendRef, (snap) => {
    weekendData = snap.exists() ? ({ ...snap.data(), weekend_id: snap.id } as Weekend) : null;
    onUpdate({ weekend: weekendData, sessions: sessionsData, assignments: assignmentsData, communityAssignments: communityData });
  });

  const unsubSessions = onSnapshot(sessionsQuery, (snap) => {
    sessionsData = snap.docs.map((d) => ({ ...d.data(), session_id: d.id } as Session));
    onUpdate({ weekend: weekendData, sessions: sessionsData, assignments: assignmentsData, communityAssignments: communityData });
  });

  const unsubAssignments = onSnapshot(assignmentsQuery, (snap) => {
    assignmentsData = snap.docs.map((d) => ({ ...d.data(), assignment_id: d.id } as Assignment));
    onUpdate({ weekend: weekendData, sessions: sessionsData, assignments: assignmentsData, communityAssignments: communityData });
  });

  const unsubCommunity = onSnapshot(communityQuery, (snap) => {
    communityData = snap.docs.map((d) => ({ ...d.data(), community_assignment_id: d.id } as CommunityAssignment));
    onUpdate({ weekend: weekendData, sessions: sessionsData, assignments: assignmentsData, communityAssignments: communityData });
  });

  return () => {
    unsubWeekend();
    unsubSessions();
    unsubAssignments();
    unsubCommunity();
  };
}

/**
 * Real-time listener for the active officers list.
 */
export function subscribeToPeople(onUpdate: (people: Person[]) => void) {
  const peopleQuery = query(collection(db, 'people'), where('aktif', '==', true), orderBy('nama', 'asc'));
  return onSnapshot(peopleQuery, (snap) => {
    const people = snap.docs.map((d) => ({ ...d.data(), person_id: d.id } as Person));
    onUpdate(people);
  });
}
'@
Set-Content -Path "frontend/src/services/api.ts" -Value $apiServiceCode
)

command($selectOfficerModalCode = @'
import { useState, useMemo } from 'react';
import { Dialog, Button, Input, Badge } from '../ui';
import type { Person, RoleConfig, Assignment } from '../../types';

interface SelectOfficerModalProps {
  open: boolean;
  onClose: () => void;
  role: RoleConfig | null;
  sessionName: string;
  currentAssignments: Assignment[];
  availablePeople: (Person & { lastAssignedAt?: string; namaLingkungan?: string })[];
  onSave: (personIds: string[], overrideReason?: string) => Promise<void>;
  isAdmin: boolean;
}

export default function SelectOfficerModal({
  open,
  onClose,
  role,
  sessionName,
  currentAssignments,
  availablePeople,
  onSave,
  isAdmin,
}: SelectOfficerModalProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [overrideReason, setOverrideReason] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sortByLru, setSortByLru] = useState(false);

  if (!role) return null;

  const currentCount = currentAssignments.filter((a) => a.role_id === role.role_id).length;
  const remainingQuota = Math.max(0, role.jumlah_maksimal - currentCount);

  // Filter & Sort candidates
  const filteredCandidates = useMemo(() => {
    let list = availablePeople.filter((p) => {
      // Exclude already assigned in this session
      const alreadyInSession = currentAssignments.some(
        (a) => a.person_id === p.person_id && a.role_id === role.role_id
      );
      if (alreadyInSession) return false;

      const q = searchQuery.toLowerCase();
      const matchName = p.nama.toLowerCase().includes(q);
      const matchLingkungan = p.namaLingkungan ? p.namaLingkungan.toLowerCase().includes(q) : false;
      return matchName || matchLingkungan;
    });

    if (sortByLru) {
      list = [...list].sort((a, b) => {
        const timeA = a.lastAssignedAt ? new Date(a.lastAssignedAt).getTime() : 0;
        const timeB = b.lastAssignedAt ? new Date(b.lastAssignedAt).getTime() : 0;
        return timeA - timeB;
      });
    }

    return list;
  }, [availablePeople, currentAssignments, role.role_id, searchQuery, sortByLru]);

  const handleTogglePerson = (personId: string) => {
    if (selectedIds.includes(personId)) {
      setSelectedIds(selectedIds.filter((id) => id !== personId));
    } else {
      if (selectedIds.length < remainingQuota) {
        setSelectedIds([...selectedIds, personId]);
      }
    }
  };

  const handleSave = async () => {
    if (selectedIds.length === 0) return;
    try {
      setIsSubmitting(true);
      await onSave(selectedIds, overrideReason);
      setSelectedIds([]);
      setOverrideReason('');
      onClose();
    } catch (error) {
      console.error('Failed to assign officers:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} title={`Pilih ${role.nama_peran}`}>
      <div className="space-y-4">
        {/* Quota & Session Info */}
        <div className="flex items-center justify-between bg-surface p-3 rounded-xl border border-surface-muted text-sm">
          <div>
            <span className="text-ink-soft block text-xs">Sesi Misa</span>
            <span className="font-bold text-ink">{sessionName}</span>
          </div>
          <div className="text-right">
            <span className="text-ink-soft block text-xs">Sisa Kuota</span>
            <span className="font-bold text-ink">
              {remainingQuota - selectedIds.length} / {role.jumlah_maksimal} tempat
            </span>
          </div>
        </div>

        {/* Search and LRU Toggle */}
        <div className="flex gap-2">
          <Input
            label="Cari Petugas"
            placeholder="Ketik nama atau lingkungan..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="flex-1"
          />
          <div className="flex items-end">
            <button
              type="button"
              onClick={() => setSortByLru(!sortByLru)}
              className={`h-11 min-h-[44px] px-3 rounded-lg text-xs font-bold transition-colors cursor-pointer border ${
                sortByLru
                  ? 'bg-accent text-ink border-ink'
                  : 'bg-white text-ink-soft border-surface-muted hover:bg-surface-muted'
              }`}
              title="Urutkan berdasarkan yang paling lama/belum pernah bertugas"
            >
              ★ Saran (LRU)
            </button>
          </div>
        </div>

        {/* Candidates List */}
        <div className="max-h-60 overflow-y-auto space-y-2 pr-1">
          {filteredCandidates.length === 0 ? (
            <p className="text-center py-6 text-sm text-ink-soft">Tidak ada petugas yang cocok.</p>
          ) : (
            filteredCandidates.map((person) => {
              const isSelected = selectedIds.includes(person.person_id);
              const disabled = !isSelected && selectedIds.length >= remainingQuota;

              return (
                <div
                  key={person.person_id}
                  onClick={() => !disabled && handleTogglePerson(person.person_id)}
                  className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer ${
                    isSelected
                      ? 'bg-accent/20 border-ink font-bold'
                      : disabled
                      ? 'opacity-40 border-surface-muted cursor-not-allowed bg-surface'
                      : 'bg-white border-surface-muted hover:border-ink-soft'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      disabled={disabled}
                      onChange={() => {}}
                      className="w-4 h-4 rounded text-ink focus:ring-accent accent-ink cursor-pointer"
                    />
                    <div>
                      <div className="text-ink text-sm font-medium">{person.nama}</div>
                      <div className="text-xs text-ink-soft">{person.namaLingkungan || 'Lingkungan'}</div>
                    </div>
                  </div>

                  <div className="text-right">
                    {person.lastAssignedAt ? (
                      <span className="text-[11px] text-ink-soft">
                        Terakhir: {new Date(person.lastAssignedAt).toLocaleDateString('id-ID', { month: 'short', day: 'numeric' })}
                      </span>
                    ) : (
                      <Badge variant="success">Belum pernah</Badge>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Admin Override Reason */}
        {isAdmin && (
          <Input
            label="Alasan Override (Jika Ada Peringatan Aturan)"
            placeholder="Contoh: Menggantikan petugas yang berhalangan..."
            value={overrideReason}
            onChange={(e) => setOverrideReason(e.target.value)}
          />
        )}

        {/* Action Buttons */}
        <div className="flex justify-end gap-2 pt-2 border-t border-surface-muted">
          <Button variant="secondary" onClick={onClose} disabled={isSubmitting}>
            Batal
          </Button>
          <Button
            variant="primary"
            onClick={handleSave}
            disabled={selectedIds.length === 0 || isSubmitting}
          >
            {isSubmitting ? 'Menyimpan...' : `Tugaskan (${selectedIds.length})`}
