import { useState } from 'react';
import { Dialog, Button, Input } from '../ui';
import type { SessionType } from '../../types';

interface CreateWeekendModalProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: {
    tanggalAcuan: string;
    sessions: { jenis_sesi: SessionType; nama_khusus?: string; tanggal_sesi: string }[];
  }) => Promise<void>;
}

export default function CreateWeekendModal({ open, onClose, onSubmit }: CreateWeekendModalProps) {
  const [selectedSunday, setSelectedSunday] = useState('');
  const [includeSabtuSore, setIncludeSabtuSore] = useState(true);
  const [includeMingguPagi, setIncludeMingguPagi] = useState(true);
  const [includeMingguSore, setIncludeMingguSore] = useState(true);

  // Special Session
  const [hasSpecialSession, setHasSpecialSession] = useState(false);
  const [specialSessionName, setSpecialSessionName] = useState('');
  const [specialSessionDate, setSpecialSessionDate] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!selectedSunday) return;

    const sessions: { jenis_sesi: SessionType; nama_khusus?: string; tanggal_sesi: string }[] = [];
    const sundayDate = new Date(selectedSunday);
    const saturdayDate = new Date(sundayDate);
    saturdayDate.setDate(sundayDate.getDate() - 1);

    if (includeSabtuSore) {
      sessions.push({
        jenis_sesi: 'SABTU_SORE',
        tanggal_sesi: saturdayDate.toISOString()
      });
    }
    if (includeMingguPagi) {
      sessions.push({
        jenis_sesi: 'MINGGU_PAGI',
        tanggal_sesi: sundayDate.toISOString()
      });
    }
    if (includeMingguSore) {
      sessions.push({
        jenis_sesi: 'MINGGU_SORE',
        tanggal_sesi: sundayDate.toISOString()
      });
    }

    if (hasSpecialSession && specialSessionName && specialSessionDate) {
      sessions.push({
        jenis_sesi: 'KHUSUS',
        nama_khusus: specialSessionName,
        tanggal_sesi: new Date(specialSessionDate).toISOString()
      });
    }

    try {
      setIsSubmitting(true);
      await onSubmit({ tanggalAcuan: selectedSunday, sessions });
      onClose();
    } catch (error) {
      console.error('Failed to create weekend:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} title="Buka / Buat Akhir Pekan">
      <div className="space-y-5">
        <Input
          type="date"
          label="Pilih Tanggal Hari Minggu"
          value={selectedSunday}
          onChange={(e) => setSelectedSunday(e.target.value)}
        />

        <div>
          <label className="block text-xs font-bold uppercase text-ink-soft mb-2">
            Centang Sesi Misa yang Diadakan
          </label>
          <div className="space-y-2 bg-surface p-3 rounded-xl border border-surface-muted">
            <label className="flex items-center gap-3 text-sm font-medium text-ink cursor-pointer">
              <input
                type="checkbox"
                checked={includeSabtuSore}
                onChange={(e) => setIncludeSabtuSore(e.target.checked)}
                className="w-4 h-4 rounded text-ink accent-ink"
              />
              Sabtu Sore (17.00 WIB)
            </label>
            <label className="flex items-center gap-3 text-sm font-medium text-ink cursor-pointer">
              <input
                type="checkbox"
                checked={includeMingguPagi}
                onChange={(e) => setIncludeMingguPagi(e.target.checked)}
                className="w-4 h-4 rounded text-ink accent-ink"
              />
              Minggu Pagi (08.00 WIB)
            </label>
            <label className="flex items-center gap-3 text-sm font-medium text-ink cursor-pointer">
              <input
                type="checkbox"
                checked={includeMingguSore}
                onChange={(e) => setIncludeMingguSore(e.target.checked)}
                className="w-4 h-4 rounded text-ink accent-ink"
              />
              Minggu Sore (17.00 WIB)
            </label>
          </div>
        </div>

        {/* Sesi Khusus (Easter, Christmas, etc.) */}
        <div className="border-t border-surface-muted pt-3">
          <label className="flex items-center gap-3 text-sm font-bold text-ink cursor-pointer mb-2">
            <input
              type="checkbox"
              checked={hasSpecialSession}
              onChange={(e) => setHasSpecialSession(e.target.checked)}
              className="w-4 h-4 rounded text-ink accent-ink"
            />
            + Tambah Sesi Misa Khusus
          </label>

          {hasSpecialSession && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 bg-surface p-3 rounded-xl border border-surface-muted">
              <Input
                label="Nama Misa Khusus"
                placeholder="Misal: Misa Paskah"
                value={specialSessionName}
                onChange={(e) => setSpecialSessionName(e.target.value)}
              />
              <Input
                type="datetime-local"
                label="Tanggal & Waktu"
                value={specialSessionDate}
                onChange={(e) => setSpecialSessionDate(e.target.value)}
              />
            </div>
          )}
        </div>

        <div className="flex justify-end gap-2 pt-2 border-t border-surface-muted">
          <Button variant="secondary" onClick={onClose} disabled={isSubmitting}>
            Batal
          </Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={!selectedSunday || isSubmitting}
          >
            {isSubmitting ? 'Memproses...' : 'Buka / Buat Jadwal'}
          </Button>
        </div>
      </div>
    </Dialog>
  );
}
