$appCode = @'
import { useState } from 'react';
import { Layout } from './components/layout';
import { SchedulingWorkspace } from './components/scheduling';
import { CalendarView, PrintScheduleView } from './components/calendar';
import {
  ManageOfficersTab,
  RuleSettingsTab,
  AuditLogsTab,
  UserManagementTab
} from './components/admin';
import { AuthProvider, useAuth } from './context/AuthContext';
import type { TabId } from './types';

function MainContent() {
  const [activeTab, setActiveTab] = useState<TabId>('penjadwalan');
  const [isPrintView, setIsPrintView] = useState(false);
  const { user } = useAuth();

  const currentUser = user || {
    email: 'admin@paroki.org',
    role: 'ADMIN',
    displayName: 'Admin Paroki'
  };

  if (isPrintView) {
    return (
      <div className="max-w-[76rem] mx-auto p-4 md:p-8">
        <PrintScheduleView onBack={() => setIsPrintView(false)} />
      </div>
    );
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'penjadwalan':
        return <SchedulingWorkspace userRole={currentUser.role} />;
      case 'kalender':
        return (
          <CalendarView
            onSelectWeekend={() => {
              setActiveTab('penjadwalan');
            }}
          />
        );
      case 'kelola-petugas':
        return <ManageOfficersTab />;
      case 'pengaturan-aturan':
        return <RuleSettingsTab />;
      case 'riwayat-audit':
        return <AuditLogsTab />;
      case 'pengguna':
        return <UserManagementTab />;
      default:
        return null;
    }
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab} user={currentUser}>
      {renderContent()}
    </Layout>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <MainContent />
    </AuthProvider>
  );
}
