  const handleToggleRoleForPerson = (roleName: string) => {
    if (!editingPerson) return;
    const current = editingPerson.peranList || [];
    const updated = current.includes(roleName)
      ? current.filter((r) => r !== roleName)
      : [...current, roleName];

    const updatedPerson = { ...editingPerson, peranList: updated };
    setEditingPerson(updatedPerson);
    setPeople(people.map((p) => (p.person_id === editingPerson.person_id ? updatedPerson : p)));
