      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-display font-bold text-ink">Kelola Petugas Liturgi ({people.length} Orang)</h1>
          <p className="text-sm text-ink-soft">
            Data resmi seluruh 172 petugas liturgi paroki, wilayah, lingkungan, dan kelayakan peran.
          </p>
        </div>
        <Button variant="primary" onClick={() => setIsAddModalOpen(true)}>
          + Tambah Petugas
        </Button>
      </div>

      <Card>
        {/* Search */}
        <div className="mb-4">
          <Input
            label="Cari Petugas / Lingkungan / Wilayah"
            placeholder="Ketik nama petugas, nama lingkungan, atau wilayah..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {/* Table */}
        <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
          <table className="w-full text-left text-sm">
            <thead className="border-b border-surface-muted text-xs uppercase text-ink-soft bg-surface sticky top-0 z-10">
              <tr>
                <th className="p-3">Nama Petugas</th>
                <th className="p-3">Wilayah / Lingkungan</th>
                <th className="p-3">Peran yang Dimiliki</th>
                <th className="p-3">Status</th>
                <th className="p-3 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-surface-muted">
              {filteredPeople.map((person) => (
                <tr key={person.person_id} className="hover:bg-surface/50 transition-colors">
                  <td className="p-3 font-bold text-ink">{person.nama}</td>
                  <td className="p-3 text-ink-soft text-xs">
                    <div className="font-medium text-ink">{person.namaWilayah}</div>
                    <div>Lingkungan {person.namaLingkungan}</div>
                  </td>
                  <td className="p-3">
                    <div className="flex flex-wrap gap-1">
                      {person.peranList && person.peranList.length > 0 ? (
                        person.peranList.map((r) => <Chip key={r} label={r} />)
                      ) : (
                        <span className="text-xs text-ink-soft italic">Belum ada peran</span>
                      )}
                    </div>
                  </td>
                  <td className="p-3">
                    <Badge variant={person.aktif ? 'complete' : 'danger'}>
                      {person.aktif ? 'Aktif' : 'Nonaktif'}
                    </Badge>
                  </td>
                  <td className="p-3 text-right space-x-2 whitespace-nowrap">
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => setEditingPerson(person)}
                    >
                      Kelola Peran
                    </Button>
                    <Button
                      variant={person.aktif ? 'ghost' : 'secondary'}
                      size="sm"
                      onClick={() => handleToggleActive(person.person_id)}
                    >
                      {person.aktif ? 'Nonaktifkan' : 'Aktifkan'}
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Add Person Modal */}
      <Dialog open={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} title="Tambah Petugas Baru">
        <div className="space-y-4">
          <Input
            label="Nama Lengkap Petugas"
            placeholder="Contoh: Yohanes Maria..."
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
          />
          <Input
            label="Lingkungan"
            placeholder="Contoh: TIMOTIUS..."
            value={newLingkungan}
            onChange={(e) => setNewLingkungan(e.target.value)}
          />
          <div className="flex justify-end gap-2 pt-2 border-t border-surface-muted">
            <Button variant="secondary" onClick={() => setIsAddModalOpen(false)}>
              Batal
            </Button>
            <Button variant="primary" onClick={handleAddPerson} disabled={!newName}>
              Simpan Petugas
            </Button>
          </div>
        </div>
      </Dialog>

      {/* Manage Roles Modal */}
      {editingPerson && (
        <Dialog open={!!editingPerson} onClose={() => setEditingPerson(null)} title={`Kelola Peran: ${editingPerson.nama}`}>
          <div className="space-y-4">
            <p className="text-xs text-ink-soft">
