              })}
            </div>
            <div className="flex justify-end pt-2 border-t border-surface-muted">
              <Button variant="primary" onClick={() => setEditingPerson(null)}>
                Selesai
              </Button>
            </div>
          </div>
        </Dialog>
      )}
    </div>
  );
}
