  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sortByLru, setSortByLru] = useState(false);

  const currentRoleId = role?.role_id;
  const maxQuota = role?.jumlah_maksimal || 1;
  const currentCount = currentAssignments.filter((a) => a.role_id === currentRoleId).length;
  const remainingQuota = Math.max(0, maxQuota - currentCount);

  // Filter & Sort candidates (All hooks at top level)
  const filteredCandidates = useMemo(() => {
    if (!currentRoleId) return [];

    let list = availablePeople.filter((p) => {
      const alreadyInSession = currentAssignments.some(
        (a) => a.person_id === p.person_id && a.role_id === currentRoleId
      );
      if (alreadyInSession) return false;

      const q = searchQuery.toLowerCase();
      const matchName = p.nama.toLowerCase().includes(q);
      const matchLingkungan = p.namaLingkungan ? p.namaLingkungan.toLowerCase().includes(q) : false;
      return matchName || matchLingkungan;
    });

    if (sortByLru) {
      list = [...list].sort((a, b) => {
        const timeA = a.lastAssignedAt ? new Date(a.lastAssignedAt).getTime() : 0;
        const timeB = b.lastAssignedAt ? new Date(b.lastAssignedAt).getTime() : 0;
        return timeA - timeB;
      });
    }

    return list;
  }, [availablePeople, currentAssignments, currentRoleId, searchQuery, sortByLru]);

  if (!open || !role) return null;

  const handleTogglePerson = (personId: string) => {
    if (selectedIds.includes(personId)) {
      setSelectedIds(selectedIds.filter((id) => id !== personId));
    } else {
      if (selectedIds.length < remainingQuota) {
        setSelectedIds([...selectedIds, personId]);
      }
    }
  };

  const handleSave = async () => {
    if (selectedIds.length === 0) return;
    try {
      setIsSubmitting(true);
      await onSave(selectedIds, overrideReason);
      setSelectedIds([]);
      setOverrideReason('');
      onClose();
    } catch (error) {
      console.error('Failed to assign officers:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} title={`Pilih ${role.nama_peran}`}>
      <div className="space-y-4">
        {/* Quota & Session Info */}
        <div className="flex items-center justify-between bg-surface p-3 rounded-xl border border-surface-muted text-sm">
          <div>
            <span className="text-ink-soft block text-xs">Sesi Misa</span>
            <span className="font-bold text-ink">{sessionName}</span>
          </div>
          <div className="text-right">
            <span className="text-ink-soft block text-xs">Sisa Kuota</span>
            <span className="font-bold text-ink">
              {remainingQuota - selectedIds.length} / {role.jumlah_maksimal} tempat
            </span>
          </div>
        </div>

        {/* Search and LRU Toggle */}
        <div className="flex gap-2">
          <Input
            label="Cari Petugas"
            placeholder="Ketik nama atau lingkungan..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="flex-1"
          />
          <div className="flex items-end">
            <button
              type="button"
              onClick={() => setSortByLru(!sortByLru)}
              className={`h-11 min-h-[44px] px-3 rounded-lg text-xs font-bold transition-colors cursor-pointer border ${
                sortByLru
                  ? 'bg-accent text-ink border-ink'
                  : 'bg-white text-ink-soft border-surface-muted hover:bg-surface-muted'
              }`}
              title="Urutkan berdasarkan yang paling lama/belum pernah bertugas"
            >
              ★ Saran (LRU)
            </button>
          </div>
        </div>

        {/* Candidates List */}
        <div className="max-h-60 overflow-y-auto space-y-2 pr-1">
          {filteredCandidates.length === 0 ? (
            <p className="text-center py-6 text-sm text-ink-soft">Tidak ada petugas yang cocok.</p>
          ) : (
            filteredCandidates.map((person) => {
              const isSelected = selectedIds.includes(person.person_id);
              const disabled = !isSelected && selectedIds.length >= remainingQuota;

              return (
                <div
                  key={person.person_id}
                  onClick={() => !disabled && handleTogglePerson(person.person_id)}
                  className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer ${
                    isSelected
                      ? 'bg-accent/20 border-ink font-bold'
                      : disabled
                      ? 'opacity-40 border-surface-muted cursor-not-allowed bg-surface'
                      : 'bg-white border-surface-muted hover:border-ink-soft'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      disabled={disabled}
                      onChange={() => {}}
                      className="w-4 h-4 rounded text-ink focus:ring-accent accent-ink cursor-pointer"
                    />
                    <div>
                      <div className="text-ink text-sm font-medium">{person.nama}</div>
                      <div className="text-xs text-ink-soft">{person.namaLingkungan || 'Lingkungan'}</div>
                    </div>
                  </div>

                  <div className="text-right">
                    {person.lastAssignedAt ? (
                      <span className="text-[11px] text-ink-soft">
                        Terakhir: {new Date(person.lastAssignedAt).toLocaleDateString('id-ID', { month: 'short', day: 'numeric' })}
                      </span>
                    ) : (
                      <Badge variant="success">Belum pernah</Badge>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Admin Override Reason */}
        {isAdmin && (
          <Input
            label="Alasan Override (Jika Ada Peringatan Aturan)"
            placeholder="Contoh: Menggantikan petugas yang berhalangan..."
            value={overrideReason}
            onChange={(e) => setOverrideReason(e.target.value)}
          />
        )}

        {/* Action Buttons */}
        <div className="flex justify-end gap-2 pt-2 border-t border-surface-muted">
          <Button variant="secondary" onClick={onClose} disabled={isSubmitting}>
            Batal
          </Button>
          <Button
            variant="primary"
            onClick={handleSave}
            disabled={selectedIds.length === 0 || isSubmitting}
          >
            {isSubmitting ? 'Menyimpan...' : `Tugaskan (${selectedIds.length})`}
          </Button>
        </div>
      </div>
    </Dialog>
  );
}
'@

