  const handleNextMonth = () => setCurrentDate(new Date(year, month + 1, 1));
  const handleToday = () => setCurrentDate(new Date());

  const calendarDays = useMemo(() => {
    const firstDayIndex = (new Date(year, month, 1).getDay() + 6) % 7; // Monday = 0, Sunday = 6
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const daysInPrevMonth = new Date(year, month, 0).getDate();

    const days: {
      dayNumber: number;
      dateStr: string;
      isCurrentMonth: boolean;
      isSaturday: boolean;
      isSunday: boolean;
      matchingSundayStr: string;
    }[] = [];

    // Previous month filler
    for (let i = firstDayIndex - 1; i >= 0; i--) {
      const d = daysInPrevMonth - i;
      const dObj = new Date(year, month - 1, d);
      const dateStr = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      days.push({
        dayNumber: d,
        dateStr,
        isCurrentMonth: false,
        isSaturday: dObj.getDay() === 6,
        isSunday: dObj.getDay() === 0,
        matchingSundayStr: dateStr
      });
    }

    // Current month days
    for (let d = 1; d <= daysInMonth; d++) {
      const dObj = new Date(year, month, d);
      const dayOfWeek = dObj.getDay();
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

      let matchingSundayStr = dateStr;
      if (dayOfWeek === 6) {
        const nextDay = new Date(year, month, d + 1);
        matchingSundayStr = `${nextDay.getFullYear()}-${String(nextDay.getMonth() + 1).padStart(2, '0')}-${String(nextDay.getDate()).padStart(2, '0')}`;
      }

      days.push({
        dayNumber: d,
        dateStr,
        isCurrentMonth: true,
        isSaturday: dayOfWeek === 6,
        isSunday: dayOfWeek === 0,
        matchingSundayStr
      });
    }

    // Next month filler
    const totalCells = Math.ceil(days.length / 7) * 7;
    const remaining = totalCells - days.length;
    for (let d = 1; d <= remaining; d++) {
      const dObj = new Date(year, month + 1, d);
      const dateStr = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
