        <div className="grid grid-cols-7 divide-x divide-y divide-surface-muted">
          {calendarDays.map((item, index) => {
            const isWeekendDay = item.isSaturday || item.isSunday;
            // Match regular weekend by Sunday date or direct match on dateStr for special masses
            const existingSchedule = schedules.find((s) =>
              s.tanggalAcuan === item.dateStr || (isWeekendDay && s.tanggalAcuan === item.matchingSundayStr && !s.isSpecialMass)
            );

            return (
              <div
                key={index}
                className={`min-h-[125px] p-2 flex flex-col justify-between transition-all group ${
                  !item.isCurrentMonth
                    ? 'bg-surface/30 opacity-40'
