command($sessionCardCode = @'
import type { ChangeEvent } from 'react';
import { Card, Chip, Select } from '../ui';
import type { Session, Assignment, CommunityAssignment, RoleConfig } from '../../types';

interface SessionCardProps {
  session: Session;
  wave: 1 | 2 | 3;
  assignments: Assignment[];
  communityAssignments: CommunityAssignment[];
  roles: RoleConfig[];
  onOpenSelectModal: (sessionId: string, sessionName: string, role: RoleConfig) => void;
  onAssignCommunity: (sessionId: string, type: 'PADUAN_SUARA' | 'TATIB', value: string) => boolean | void;
  onRemoveAssignment: (assignmentId: string) => void;
  wilayahOptions: { value: string; label: string }[];
  lingkunganOptions: { value: string; label: string }[];
}

const SPECIAL_WILAYAH = ['Grasia', 'Luar Paroki', 'Becanbo', 'Lain Lain'];

export default function SessionCard({
  session,
  wave,
  assignments,
  communityAssignments,
  roles,
  onOpenSelectModal,
  onAssignCommunity,
  onRemoveAssignment,
  wilayahOptions,
  lingkunganOptions,
}: SessionCardProps) {
  const getAssignments = (roleId: string) =>
    assignments.filter((a) => a.session_id === session.session_id && a.role_id === roleId);

  const currentChoirAssigned = communityAssignments.find(
    (c) => c.session_id === session.session_id && c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED'
  );

  const currentTatibAssigned = communityAssignments.find(
    (c) => c.session_id === session.session_id && c.jenis_penugasan === 'TATIB' && c.status !== 'REMOVED'
  );

  // BR-013: Find Wilayah already assigned to Choir in OTHER sessions of this weekend
  const otherChoirWilayah = communityAssignments
    .filter(
      (c) =>
        c.jenis_penugasan === 'PADUAN_SUARA' &&
        c.session_id !== session.session_id &&
        c.status !== 'REMOVED' &&
        c.wilayah_id &&
        !SPECIAL_WILAYAH.includes(c.wilayah_id)
    )
    .map((c) => c.wilayah_id as string);

  // Filter or mark Wilayah dropdown options according to BR-013
  const filteredWilayahOptions = wilayahOptions.map((opt) => {
    const isConflict = otherChoirWilayah.includes(opt.value);
    return {
      value: opt.value,
      label: isConflict ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)` : opt.label,
      disabled: isConflict
    };
  });

  // BR-041: Find Lingkungan already assigned to Tatib in OTHER sessions
  const otherTatibLingkungan = communityAssignments
    .filter(
      (c) =>
        c.jenis_penugasan === 'TATIB' &&
        c.session_id !== session.session_id &&
        c.status !== 'REMOVED' &&
        c.lingkungan_id
    )
    .map((c) => c.lingkungan_id as string);

  const filteredLingkunganOptions = lingkunganOptions.map((opt) => {
    const isConflict = otherTatibLingkungan.includes(opt.value);
    return {
      value: opt.value,
      label: isConflict ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)` : opt.label,
      disabled: isConflict
    };
  });

  const renderIndividualRole = (roleId: string) => {
    const role = roles.find((r) => r.role_id === roleId) || {
      role_id: roleId,
      nama_peran: roleId,
      jumlah_dibutuhkan: 1,
      jumlah_maksimal: 1,
      aktif: true,
      urutan: 0
    };

    const currentList = getAssignments(roleId);
    const count = currentList.length;
    const isFull = count >= role.jumlah_maksimal;

    return (
      <div key={roleId} className="border-b border-surface-muted pb-3 last:border-0 last:pb-0">
        <div className="flex justify-between items-center mb-1.5">
          <span className="font-bold text-ink text-sm">{role.nama_peran}</span>
          <span className={`text-xs ${count >= role.jumlah_dibutuhkan ? 'text-ink font-bold' : 'text-ink-soft'}`}>
            {count}/{role.jumlah_dibutuhkan} terisi
          </span>
        </div>

        <div className="flex flex-wrap gap-1.5 mb-2">
          {currentList.map((a) => (
            <Chip
              key={a.assignment_id}
              label={a.person_id}
              onRemove={() => onRemoveAssignment(a.assignment_id)}
            />
          ))}
        </div>

        {!isFull && (
          <button
            type="button"
            onClick={() => onOpenSelectModal(session.session_id, session.nama_khusus || session.jenis_sesi, role)}
            className="w-full h-10 min-h-[40px] rounded-lg border border-surface-muted bg-surface px-3 text-left text-ink-soft text-xs font-bold hover:bg-surface-muted hover:text-ink transition-colors flex justify-between items-center cursor-pointer"
          >
            <span>+ Pilih {role.nama_peran}...</span>
            <span className="text-base leading-none">+</span>
          </button>
        )}
      </div>
    );
  };

  const displayName = session.nama_khusus || 
    (session.jenis_sesi === 'SABTU_SORE' ? 'Sabtu Sore - 17.00 WIB' :
     session.jenis_sesi === 'MINGGU_PAGI' ? 'Minggu Pagi - 08.00 WIB' :
     session.jenis_sesi === 'MINGGU_SORE' ? 'Minggu Sore - 17.00 WIB' : 'Sesi Khusus');

  return (
    <Card className="mb-4">
      <div className="border-b border-surface-muted pb-3 mb-4 flex justify-between items-center">
        <h3 className="text-lg font-display font-bold text-ink">{displayName}</h3>
        {session.nama_khusus && (
          <span className="text-xs bg-lilac-soft text-ink px-2.5 py-0.5 rounded-full font-bold">
            Misa Khusus
          </span>
        )}
      </div>

      <div className="space-y-4">
        {wave === 1 && (
          <>
            {/* Paduan Suara (Wilayah) */}
            <div className="border-b border-surface-muted pb-3">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-xs font-bold uppercase text-ink-soft">
                  Paduan Suara (Wilayah)
                </label>
                {currentChoirAssigned && (
                  <span className="text-xs font-bold text-ink bg-accent/30 px-2 py-0.5 rounded-full">
                    Terpilih: {currentChoirAssigned.wilayah_id}
                  </span>
                )}
              </div>

              <div className="flex gap-2 items-center">
                <div className="flex-1">
                  <Select
                    value={currentChoirAssigned?.wilayah_id || ''}
                    options={filteredWilayahOptions}
                    placeholder="-- Pilih Wilayah Koor --"
                    onChange={(e: ChangeEvent<HTMLSelectElement>) => {
                      const val = e.target.value;
                      if (!val) return;
                      onAssignCommunity(session.session_id, 'PADUAN_SUARA', val);
                    }}
                  />
                </div>
                {currentChoirAssigned && (
                  <button
                    type="button"
                    onClick={() => onRemoveAssignment(currentChoirAssigned.community_assignment_id)}
                    className="h-11 px-3 text-xs text-danger hover:bg-danger/10 rounded-lg font-bold border border-danger/20 cursor-pointer"
                    title="Batalkan penugasan koor"
                  >
                    Batal
                  </button>
                )}
              </div>
            </div>

            {/* Organis & Pemazmur */}
            {renderIndividualRole('ROL-ORGANIS')}
            {renderIndividualRole('ROL-PEMAZMUR')}
          </>
        )}

        {wave === 2 && (
          <>
            {renderIndividualRole('ROL-LEKTOR')}
            {renderIndividualRole('ROL-MISDINAR')}
            {renderIndividualRole('ROL-PRODIAKON')}
          </>
        )}

        {wave === 3 && (
          <>
            {/* Tatib (Lingkungan) */}
            <div className="border-b border-surface-muted pb-3">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-xs font-bold uppercase text-ink-soft">
                  Tatib (Lingkungan)
                </label>
                {currentTatibAssigned && (
                  <span className="text-xs font-bold text-ink bg-accent/30 px-2 py-0.5 rounded-full">
                    Terpilih: Lingkungan {currentTatibAssigned.lingkungan_id}
                  </span>
                )}
              </div>

              <div className="flex gap-2 items-center">
                <div className="flex-1">
                  <Select
                    value={currentTatibAssigned?.lingkungan_id || ''}
                    options={filteredLingkunganOptions}
                    placeholder="-- Pilih Lingkungan Tatib --"
                    onChange={(e: ChangeEvent<HTMLSelectElement>) => {
                      const val = e.target.value;
                      if (!val) return;
                      onAssignCommunity(session.session_id, 'TATIB', val);
                    }}
                  />
                </div>
                {currentTatibAssigned && (
                  <button
                    type="button"
                    onClick={() => onRemoveAssignment(currentTatibAssigned.community_assignment_id)}
                    className="h-11 px-3 text-xs text-danger hover:bg-danger/10 rounded-lg font-bold border border-danger/20 cursor-pointer"
                    title="Batalkan penugasan tatib"
                  >
                    Batal
                  </button>
                )}
              </div>
            </div>

            <p className="text-xs text-ink-soft italic">
              * Hias Altar diatur satu kali per akhir pekan (bukan per sesi misa).
            </p>
          </>
        )}
      </div>
    </Card>
  );
}
'@

