        c.status !== 'REMOVED' &&
        c.lingkungan_id
    )
    .map((c) => c.lingkungan_id as string);

  const filteredTatibOptions = lingkunganOptions.map((opt) => {
    const isConflict = otherTatibLingkungan.includes(opt.value);
    const isAlreadyInThisSession = sessionTatibList.some((c) => c.lingkungan_id === opt.value);
    return {
      value: opt.value,
      label: isConflict
        ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)`
        : isAlreadyInThisSession
        ? `✓ ${opt.label} (Sudah ditambahkan)`
        : opt.label,
      disabled: isConflict || isAlreadyInThisSession
    };
  });

