    };

    const currentList = getAssignments(roleId);
    const count = currentList.length;
    const isFull = count >= role.jumlah_maksimal;

    return (
      <div key={roleId} className="border-b border-surface-muted pb-3 last:border-0 last:pb-0">
        <div className="flex justify-between items-center mb-1.5">
          <span className="font-bold text-ink text-sm">{role.nama_peran}</span>
          <span className={`text-xs ${count >= role.jumlah_dibutuhkan ? 'text-ink font-bold' : 'text-ink-soft'}`}>
            {count}/{role.jumlah_dibutuhkan} terisi
          </span>
        </div>

        <div className="flex flex-wrap gap-1.5 mb-2">
          {currentList.map((a) => (
            <Chip
              key={a.assignment_id}
              label={a.person_id}
              onRemove={() => onRemoveAssignment(a.assignment_id)}
            />
          ))}
        </div>

        {!isFull && (
