            className="w-full h-10 min-h-[40px] rounded-lg border border-surface-muted bg-surface px-3 text-left text-ink-soft text-xs font-bold hover:bg-surface-muted hover:text-ink transition-colors flex justify-between items-center cursor-pointer"
          >
            <span>+ Pilih {role.nama_peran}...</span>
            <span className="text-base leading-none">+</span>
          </button>
        )}
      </div>
    );
  };

  const displayName = session.nama_khusus || 
    (session.jenis_sesi === 'SABTU_SORE' ? 'Sabtu Sore - 17.00 WIB' :
     session.jenis_sesi === 'MINGGU_PAGI' ? 'Minggu Pagi - 08.00 WIB' :
     session.jenis_sesi === 'MINGGU_SORE' ? 'Minggu Sore - 17.00 WIB' : 'Sesi Khusus');

  return (
    <Card className="mb-4">
      <div className="border-b border-surface-muted pb-3 mb-4 flex justify-between items-center">
        <h3 className="text-lg font-display font-bold text-ink">{displayName}</h3>
        {session.nama_khusus && (
          <span className="text-xs bg-lilac-soft text-ink px-2.5 py-0.5 rounded-full font-bold">
            Misa Khusus
          </span>
        )}
      </div>

      <div className="space-y-4">
        {wave === 1 && (
          <>
            {/* Paduan Suara (Lingkungan & Wilayah - Multi Assign) */}
            <div className="border-b border-surface-muted pb-3 space-y-2">
              <div className="flex justify-between items-center">
                <label className="block text-xs font-bold uppercase text-ink-soft">
                  Paduan Suara ({sessionChoirList.length} Kelompok Ditugaskan)
