                    <Chip
                      key={c.community_assignment_id}
                      label={c.lingkungan_id ? `Lingkungan ${c.lingkungan_id}` : `Wilayah ${c.wilayah_id}`}
                      onRemove={() => onRemoveAssignment(c.community_assignment_id)}
                    />
                  ))
                )}
              </div>

              {/* Add Choir Group Dropdown */}
              <div className="flex gap-2 items-center pt-1">
                {choirType === 'LINGKUNGAN' ? (
                  <Select
                    options={filteredChoirLingkunganOptions}
                    placeholder="-- Tambah Koor (Pilih Lingkungan) --"
                    onChange={(e: ChangeEvent<HTMLSelectElement>) => {
                      const val = e.target.value;
                      if (!val) return;
                      onAssignCommunity(session.session_id, 'PADUAN_SUARA', val, true);
                      e.target.value = '';
                    }}
                  />
                ) : (
                  <Select
                    options={filteredChoirWilayahOptions}
                    placeholder="-- Tambah Koor (Pilih Wilayah) --"
                    onChange={(e: ChangeEvent<HTMLSelectElement>) => {
                      const val = e.target.value;
                      if (!val) return;
                      onAssignCommunity(session.session_id, 'PADUAN_SUARA', val, false);
                      e.target.value = '';
                    }}
                  />
                )}
              </div>
            </div>

            {/* Organis & Pemazmur */}
            {renderIndividualRole('ROL-ORGANIS')}
            {renderIndividualRole('ROL-PEMAZMUR')}
          </>
        )}

        {wave === 2 && (
          <>
            {renderIndividualRole('ROL-LEKTOR')}
            {renderIndividualRole('ROL-MISDINAR')}
            {renderIndividualRole('ROL-PRODIAKON')}
          </>
        )}

        {wave === 3 && (
          <>
            {/* Tatib (Lingkungan - Multi Assign) */}
            <div className="border-b border-surface-muted pb-3 space-y-2">
              <label className="block text-xs font-bold uppercase text-ink-soft">
                Tatib ({sessionTatibList.length} Lingkungan Ditugaskan)
              </label>

              <div className="flex flex-wrap gap-1.5 min-h-[32px] p-2 bg-surface rounded-xl border border-surface-muted">
                {sessionTatibList.length === 0 ? (
                  <span className="text-xs text-ink-soft italic">Belum ada Tatib yang ditugaskan di sesi ini.</span>
                ) : (
                  sessionTatibList.map((c) => (
                    <Chip
                      key={c.community_assignment_id}
                      label={`Lingkungan ${c.lingkungan_id}`}
                      onRemove={() => onRemoveAssignment(c.community_assignment_id)}
                    />
                  ))
                )}
              </div>

              <Select
                options={filteredTatibOptions}
                placeholder="-- Tambah Tatib (Pilih Lingkungan) --"
                onChange={(e: ChangeEvent<HTMLSelectElement>) => {
                  const val = e.target.value;
                  if (!val) return;
                  onAssignCommunity(session.session_id, 'TATIB', val, true);
                  e.target.value = '';
                }}
              />
            </div>

            <p className="text-xs text-ink-soft italic">
              * Hias Altar diatur satu kali per akhir pekan (bukan per sesi misa).
            </p>
          </>
        )}
      </div>
    </Card>
  );
}
