import type { Session, Assignment, CommunityAssignment, RoleConfig } from '../../types';

interface SessionNavTabsProps {
  sessions: Session[];
  activeSessionId: string;
  onSelectSession: (sessionId: string) => void;
  assignments: Assignment[];
  communityAssignments: CommunityAssignment[];
  roles: RoleConfig[];
}

export default function SessionNavTabs({
  sessions,
  activeSessionId,
  onSelectSession,
  assignments,
  communityAssignments,
  roles,
}: SessionNavTabsProps) {
  return (
    <div className="space-y-3">
      <div className="px-1">
        <span className="text-xs font-bold uppercase tracking-wider text-ink-soft">
          Pilih Sesi Misa
        </span>
      </div>

      <div className="flex flex-col gap-2.5">
        {sessions.map((session) => {
          const isActive = session.session_id === activeSessionId;

          // Count individual filled roles
          const filledCount = roles.filter((r) => {
            const count = assignments.filter(
              (a) => a.session_id === session.session_id && a.role_id === r.role_id && a.status !== 'REMOVED'
            ).length;
            return count >= r.jumlah_dibutuhkan;
          }).length;

          // Check if choir is assigned
          const hasChoir = communityAssignments.some(
            (c) => c.session_id === session.session_id && c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED'
          );

          const totalNeeded = roles.length;
          const isAllComplete = filledCount >= totalNeeded && hasChoir;

          const sessionName =
            session.nama_khusus ||
            (session.jenis_sesi === 'SABTU_SORE'
              ? 'Sabtu Sore'
              : session.jenis_sesi === 'MINGGU_PAGI'
              ? 'Minggu Pagi'
              : session.jenis_sesi === 'MINGGU_SORE'
              ? 'Minggu Sore'
              : 'Sesi Khusus');

          const sessionTime =
            session.jenis_sesi === 'MINGGU_PAGI'
              ? '08.00 WIB'
              : session.jenis_sesi === 'SABTU_SORE' || session.jenis_sesi === 'MINGGU_SORE'
              ? '17.00 WIB'
              : '';

          return (
            <button
              key={session.session_id}
              type="button"
              onClick={() => onSelectSession(session.session_id)}
              className={`w-full p-4 rounded-2xl text-left transition-all duration-300 cursor-pointer text-sm relative overflow-hidden backdrop-blur-md ${
                isActive
                  ? 'bg-gradient-to-r from-[#D8EB73] to-[#E5F295] text-ink font-bold shadow-lg shadow-accent/25 border border-white/80 scale-[1.02]'
                  : 'bg-white/70 hover:bg-white/90 text-ink border border-white/60 shadow-sm hover:shadow-md hover:border-ink/20'
              }`}
            >
              <div className="flex justify-between items-start mb-1">
                <span className="font-display font-bold text-base block">{sessionName}</span>
                {isAllComplete ? (
                  <span className="text-[11px] bg-emerald-500/20 text-emerald-900 font-bold px-2 py-0.5 rounded-full">
                    ✓ Lengkap
                  </span>
                ) : (
                  <span className="text-[11px] bg-black/10 text-ink px-2 py-0.5 rounded-full font-medium">
                    {filledCount}/{totalNeeded} peran
                  </span>
                )}
              </div>

              {sessionTime && (
                <div className="text-xs text-ink-soft font-medium flex items-center gap-1.5">
                  <span>🕒</span>
                  <span>{sessionTime}</span>
                </div>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
'@

