command($sessionCardCode = @'
import { useState, type ChangeEvent } from 'react';
import { Card, Chip, Select } from '../ui';
import type { Session, Assignment, CommunityAssignment, RoleConfig } from '../../types';

interface SessionCardProps {
  session: Session;
  assignments: Assignment[];
  communityAssignments: CommunityAssignment[];
  roles: RoleConfig[];
  onOpenSelectModal: (sessionId: string, sessionName: string, role: RoleConfig) => void;
  onAssignCommunity: (sessionId: string, type: 'PADUAN_SUARA' | 'TATIB', value: string, isLingkungan?: boolean) => void;
  onRemoveAssignment: (assignmentId: string) => void;
  wilayahOptions: { value: string; label: string }[];
  lingkunganOptions: { value: string; label: string }[];
}

const SPECIAL_WILAYAH = ['Grasia', 'Luar Paroki', 'Becanbo', 'Lain Lain'];

export default function SessionCard({
  session,
  assignments,
  communityAssignments,
  roles,
  onOpenSelectModal,
  onAssignCommunity,
  onRemoveAssignment,
  wilayahOptions,
  lingkunganOptions,
}: SessionCardProps) {
  const [choirType, setChoirType] = useState<'WILAYAH' | 'LINGKUNGAN'>('LINGKUNGAN');

  const getAssignments = (roleId: string) =>
    assignments.filter((a) => a.session_id === session.session_id && a.role_id === roleId && a.status !== 'REMOVED');

  const sessionChoirList = communityAssignments.filter(
    (c) => c.session_id === session.session_id && c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED'
  );

  const sessionTatibList = communityAssignments.filter(
    (c) => c.session_id === session.session_id && c.jenis_penugasan === 'TATIB' && c.status !== 'REMOVED'
  );

  // BR-013: Find Wilayah already assigned to Choir in OTHER sessions
  const otherChoirWilayah = communityAssignments
    .filter(
      (c) =>
        c.jenis_penugasan === 'PADUAN_SUARA' &&
        c.session_id !== session.session_id &&
        c.status !== 'REMOVED' &&
        c.wilayah_id &&
        !SPECIAL_WILAYAH.includes(c.wilayah_id)
    )
    .map((c) => c.wilayah_id as string);

  // Find Lingkungan already assigned to Choir in ANY session
  const allChoirLingkungan = communityAssignments
    .filter((c) => c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED' && c.lingkungan_id)
    .map((c) => c.lingkungan_id as string);

  // Dropdown options for Choir (Wilayah)
  const filteredChoirWilayahOptions = wilayahOptions.map((opt) => {
    const isConflict = otherChoirWilayah.includes(opt.value);
    const isAlreadyInThisSession = sessionChoirList.some((c) => c.wilayah_id === opt.value);
    return {
      value: opt.value,
      label: isConflict
        ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)`
        : isAlreadyInThisSession
        ? `✓ ${opt.label} (Sudah ditambahkan)`
        : opt.label,
      disabled: isConflict || isAlreadyInThisSession
    };
  });

  // Dropdown options for Choir (Lingkungan)
  const filteredChoirLingkunganOptions = lingkunganOptions.map((opt) => {
    const isAlreadyInThisSession = sessionChoirList.some((c) => c.lingkungan_id === opt.value);
    const isConflictOtherSession = allChoirLingkungan.includes(opt.value) && !isAlreadyInThisSession;
    return {
      value: opt.value,
      label: isConflictOtherSession
        ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)`
        : isAlreadyInThisSession
        ? `✓ ${opt.label} (Sudah ditambahkan)`
        : opt.label,
      disabled: isAlreadyInThisSession || isConflictOtherSession
    };
  });

  // BR-041: Tatib Lingkungan options
  const otherTatibLingkungan = communityAssignments
    .filter(
      (c) =>
        c.jenis_penugasan === 'TATIB' &&
        c.session_id !== session.session_id &&
        c.status !== 'REMOVED' &&
        c.lingkungan_id
    )
    .map((c) => c.lingkungan_id as string);

  const filteredTatibOptions = lingkunganOptions.map((opt) => {
    const isConflict = otherTatibLingkungan.includes(opt.value);
    const isAlreadyInThisSession = sessionTatibList.some((c) => c.lingkungan_id === opt.value);
    return {
      value: opt.value,
      label: isConflict
        ? `⛔ ${opt.label} (Sudah dipakai di sesi lain)`
        : isAlreadyInThisSession
        ? `✓ ${opt.label} (Sudah ditambahkan)`
        : opt.label,
      disabled: isConflict || isAlreadyInThisSession
    };
  });

  const renderIndividualRole = (roleId: string) => {
    const role = roles.find((r) => r.role_id === roleId) || {
      role_id: roleId,
      nama_peran: roleId,
      jumlah_dibutuhkan: 1,
      jumlah_maksimal: 1,
      aktif: true,
      urutan: 0
    };

    const currentList = getAssignments(roleId);
    const count = currentList.length;
    const isFull = count >= role.jumlah_maksimal;

    return (
      <div key={roleId} className="p-3.5 rounded-xl bg-white/60 border border-white/80 shadow-2xs hover:bg-white/80 transition-all">
        <div className="flex justify-between items-center mb-2">
          <span className="font-bold text-ink text-sm flex items-center gap-1.5">
            <span>{role.nama_peran}</span>
          </span>
          <span
            className={`text-xs px-2.5 py-0.5 rounded-full font-bold ${
              count >= role.jumlah_dibutuhkan
                ? 'bg-emerald-500/15 text-emerald-900 border border-emerald-500/20'
                : 'bg-black/5 text-ink-soft'
            }`}
          >
            {count}/{role.jumlah_dibutuhkan} terisi
          </span>
        </div>

        <div className="flex flex-wrap gap-1.5 mb-2">
          {currentList.map((a) => (
            <Chip
              key={a.assignment_id}
              label={a.person_id}
              onRemove={() => onRemoveAssignment(a.assignment_id)}
            />
          ))}
        </div>

        {!isFull && (
          <button
            type="button"
            onClick={() => onOpenSelectModal(session.session_id, session.nama_khusus || session.jenis_sesi, role)}
            className="w-full h-10 min-h-[40px] rounded-lg border border-dashed border-ink/20 bg-white/40 px-3 text-left text-ink text-xs font-bold hover:bg-accent/30 hover:border-ink transition-all flex justify-between items-center cursor-pointer group"
          >
            <span>+ Pilih {role.nama_peran}...</span>
