command($schedulingWorkspaceCode = @'
import { useState, useEffect } from 'react';
import {
  WorkspaceHeader,
  SessionNavTabs,
  SessionCard,
  StatusPanel,
  SelectOfficerModal,
  CreateWeekendModal
} from './index';
import { REAL_OFFICERS_DATA } from '../../data/realOfficers';
import type {
  Weekend,
  Session,
  Assignment,
  CommunityAssignment,
  Person,
  RoleConfig,
  SessionProgress,
  UserRole
} from '../../types';
import { assignIndividualApi, finalizeWeekendApi, subscribeToWeekend, subscribeToPeople } from '../../services/api';

interface SchedulingWorkspaceProps {
  userRole: UserRole;
  initialWeekendId?: string;
  isSpecialMode?: boolean;
}

const DEFAULT_ROLES: RoleConfig[] = [
  { role_id: 'ROL-ORGANIS', nama_peran: 'Organis', jumlah_dibutuhkan: 1, jumlah_maksimal: 1, aktif: true, urutan: 1 },
  { role_id: 'ROL-PEMAZMUR', nama_peran: 'Pemazmur', jumlah_dibutuhkan: 2, jumlah_maksimal: 2, aktif: true, urutan: 2 },
  { role_id: 'ROL-LEKTOR', nama_peran: 'Lektor', jumlah_dibutuhkan: 3, jumlah_maksimal: 3, aktif: true, urutan: 3 },
  { role_id: 'ROL-MISDINAR', nama_peran: 'Misdinar', jumlah_dibutuhkan: 6, jumlah_maksimal: 6, aktif: true, urutan: 4 },
  { role_id: 'ROL-PRODIAKON', nama_peran: 'Prodiakon', jumlah_dibutuhkan: 6, jumlah_maksimal: 6, aktif: true, urutan: 5 },
];

const SPECIAL_WILAYAH = ['Grasia', 'Luar Paroki', 'Becanbo', 'Lain Lain'];

const INITIAL_REAL_PEOPLE: (Person & { namaLingkungan?: string; namaWilayah?: string; peranList?: string[] })[] = REAL_OFFICERS_DATA.map((o, idx) => {
  const peranList: string[] = [];
  if (o.organis) peranList.push('Organis');
  if (o.mazmur) peranList.push('Pemazmur');
  if (o.lektor) peranList.push('Lektor');
  if (o.misdinar) peranList.push('Misdinar');
  if (o.prodiakon) peranList.push('Prodiakon');

  return {
    person_id: `PER-${String(idx + 1).padStart(3, '0')}`,
    nama: o.nama,
    lingkungan_id: o.lingkungan,
    namaLingkungan: o.lingkungan,
    namaWilayah: o.wilayah,
    aktif: true,
    peranList
  };
});

export default function SchedulingWorkspace({ userRole, initialWeekendId, isSpecialMode = false }: SchedulingWorkspaceProps) {
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [selectModalState, setSelectModalState] = useState<{
    open: boolean;
    sessionId: string;
    sessionName: string;
    role: RoleConfig | null;
  }>({
    open: false,
    sessionId: '',
    sessionName: '',
    role: null
  });

  const [weekend, setWeekend] = useState<Weekend | null>({
    weekend_id: initialWeekendId || 'w-demo-2024-08-18',
    tanggal_acuan: initialWeekendId ? initialWeekendId.replace('w-', '') : '2024-08-18',
    status: 'DRAFT',
    revisi: 1
  });

  useEffect(() => {
    if (initialWeekendId) {
      setWeekend({
        weekend_id: initialWeekendId,
        tanggal_acuan: initialWeekendId.replace('w-', ''),
        status: 'DRAFT',
        revisi: 1
      });
    }
  }, [initialWeekendId]);

  const [sessions, setSessions] = useState<Session[]>([
    { session_id: 'ses-1', weekend_id: weekend?.weekend_id || 'w-demo', jenis_sesi: 'SABTU_SORE', tanggal_sesi: '2024-08-17T17:00:00Z', status: 'DRAFT' },
    { session_id: 'ses-2', weekend_id: weekend?.weekend_id || 'w-demo', jenis_sesi: 'MINGGU_PAGI', tanggal_sesi: '2024-08-18T08:00:00Z', status: 'DRAFT' },
    { session_id: 'ses-3', weekend_id: weekend?.weekend_id || 'w-demo', jenis_sesi: 'MINGGU_SORE', tanggal_sesi: '2024-08-18T17:00:00Z', status: 'DRAFT' }
  ]);

  const [activeSessionId, setActiveSessionId] = useState<string>('ses-1');

  useEffect(() => {
    if (sessions.length > 0 && !sessions.some((s) => s.session_id === activeSessionId)) {
      setActiveSessionId(sessions[0].session_id);
    }
  }, [sessions, activeSessionId]);

  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [communityAssignments, setCommunityAssignments] = useState<CommunityAssignment[]>([]);
  const [people, setPeople] = useState(INITIAL_REAL_PEOPLE);

  useEffect(() => {
    if (!weekend?.weekend_id) return;
    const unsubWeekend = subscribeToWeekend(weekend.weekend_id, (data) => {
      if (data.weekend) setWeekend(data.weekend);
      if (data.sessions.length > 0) setSessions(data.sessions);
      setAssignments(data.assignments);
      setCommunityAssignments(data.communityAssignments);
    });

    const unsubPeople = subscribeToPeople((livePeople) => {
      if (livePeople.length > 0) {
        setPeople((prev) =>
          livePeople.map((lp) => {
            const existing = prev.find((p) => p.person_id === lp.person_id);
            return {
              ...lp,
              namaLingkungan: existing?.namaLingkungan,
              namaWilayah: existing?.namaWilayah,
              peranList: existing?.peranList || []
            };
          })
        );
      }
    });

    return () => {
      unsubWeekend();
      unsubPeople();
    };
  }, [weekend?.weekend_id]);

  const progressMap: Record<string, SessionProgress[]> = {};
  sessions.forEach((s) => {
    progressMap[s.session_id] = DEFAULT_ROLES.map((role) => {
      const filled = assignments.filter((a) => a.session_id === s.session_id && a.role_id === role.role_id && a.status !== 'REMOVED').length;
      return {
        roleId: role.role_id,
        namaPeran: role.nama_peran,
        dibutuhkan: role.jumlah_dibutuhkan,
        terisi: filled,
        status: filled >= role.jumlah_dibutuhkan ? 'TERPENUHI' : 'BELUM_LENGKAP'
      };
    });
  });

  const handleOpenSelectModal = (sessionId: string, sessionName: string, role: RoleConfig) => {
    setSelectModalState({
      open: true,
      sessionId,
      sessionName,
      role
    });
  };

  const handleAssignOfficers = async (personIds: string[], overrideReason?: string) => {
    if (!weekend || !selectModalState.role) return;

    try {
      const newAssignments: Assignment[] = personIds.map((pId) => ({
        assignment_id: 'asg-temp-' + Math.random(),
        weekend_id: weekend.weekend_id,
        session_id: selectModalState.sessionId,
        person_id: people.find((p) => p.person_id === pId)?.nama || pId,
        role_id: selectModalState.role!.role_id,
        status: 'ACTIVE'
      }));
      setAssignments((prev) => [...prev, ...newAssignments]);

      await assignIndividualApi({
        weekendId: weekend.weekend_id,
        sessionId: selectModalState.sessionId,
        roleId: selectModalState.role.role_id,
        personIds,
        expectedRevision: weekend.revisi,
        overrideReason
      });
    } catch (error) {
      console.error('Assign API failed:', error);
    }
  };

  const handleAssignCommunity = (
    sessionId: string,
    type: 'PADUAN_SUARA' | 'TATIB',
    value: string,
    isLingkungan: boolean = false
  ) => {
    if (!value || !weekend) return;

    // BR-013: Block duplicate choir assignment across sessions in the same weekend
    if (!isSpecialMode && type === 'PADUAN_SUARA' && !isLingkungan && !SPECIAL_WILAYAH.includes(value)) {
      const isAlreadyInOtherSession = communityAssignments.some(
        (c) =>
          c.jenis_penugasan === 'PADUAN_SUARA' &&
          c.session_id !== sessionId &&
          c.status !== 'REMOVED' &&
          c.wilayah_id === value
      );

      if (isAlreadyInOtherSession) {
        alert(`⛔ [Aturan BR-013: Keadilan Koor Wilayah]\nWilayah "${value}" sudah ditugaskan sebagai Paduan Suara pada sesi lain di akhir pekan ini.`);
        return;
      }
    }

    // BR-041: Block duplicate tatib assignment across sessions in the same weekend
    if (!isSpecialMode && type === 'TATIB') {
      const isAlreadyInOtherSession = communityAssignments.some(
        (c) =>
          c.jenis_penugasan === 'TATIB' &&
          c.session_id !== sessionId &&
          c.status !== 'REMOVED' &&
          c.lingkungan_id === value
      );

      if (isAlreadyInOtherSession) {
        alert(`⛔ [Aturan BR-041: Keadilan Tatib Lingkungan]\nLingkungan "${value}" sudah bertugas Tatib pada sesi lain di akhir pekan ini.`);
        return;
      }
    }

    const newComm: CommunityAssignment = {
      community_assignment_id: 'comm-' + Math.random(),
      weekend_id: weekend.weekend_id,
      session_id: sessionId,
      jenis_penugasan: type,
      wilayah_id: !isLingkungan ? value : undefined,
      lingkungan_id: isLingkungan ? value : undefined,
      status: 'ACTIVE'
    };

    setCommunityAssignments((prev) => [...prev, newComm]);
  };

  const handleRemoveAssignment = (assignmentId: string) => {
    setAssignments((prev) => prev.filter((a) => a.assignment_id !== assignmentId));
    setCommunityAssignments((prev) => prev.filter((c) => c.community_assignment_id !== assignmentId));
  };

  const handleFinalize = async () => {
    if (!weekend) return;
    try {
      setWeekend((prev) => (prev ? { ...prev, status: 'FINAL', revisi: prev.revisi + 1 } : null));
      await finalizeWeekendApi({
        weekendId: weekend.weekend_id,
        expectedRevision: weekend.revisi
      });
    } catch (error) {
      console.error('Finalize API failed:', error);
    }
  };

  const activeSession = sessions.find((s) => s.session_id === activeSessionId) || sessions[0];

  return (
    <div className="w-full space-y-6">
      <WorkspaceHeader
        weekend={
          weekend
            ? {
                id: weekend.weekend_id,
                date: weekend.tanggal_acuan,
                title: `${new Date(weekend.tanggal_acuan).toLocaleDateString('id-ID', {
                  weekday: 'long',
                  day: 'numeric',
                  month: 'long',
                  year: 'numeric'
                })}`,
                status: weekend.status === 'FINAL' ? 'Final' : 'Draft',
                revision: weekend.revisi
              }
            : null
        }
        sessions={sessions.map((s) => ({
          id: s.session_id,
          name: s.nama_khusus || (s.jenis_sesi === 'SABTU_SORE' ? 'Sabtu Sore' : s.jenis_sesi === 'MINGGU_PAGI' ? 'Minggu Pagi' : 'Minggu Sore'),
          time: s.jenis_sesi === 'MINGGU_PAGI' ? '08.00' : '17.00'
        }))}
        userRole={userRole}
        onOpenWeekend={() => setIsCreateModalOpen(true)}
        onFinalize={handleFinalize}
        onPrint={() => window.print()}
      />

      {isSpecialMode && (
        <div className="p-4 bg-gradient-to-r from-accent/30 to-lilac-soft/40 border border-ink/20 rounded-2xl text-xs text-ink font-medium backdrop-blur-md">
          ✨ <strong>Mode Misa Khusus Aktif:</strong> Petugas untuk misa ini dapat ditugaskan secara bebas tanpa batasan aturan konflik / kuota.
        </div>
      )}

      {/* 3-Column Glassmorphic Layout: Left=Sessions, Middle=Active Session Card, Right=Checklist */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Left Column: Sesi Misa Navigation */}
        <div className="lg:col-span-3">
          <SessionNavTabs
            sessions={sessions}
            activeSessionId={activeSessionId}
            onSelectSession={setActiveSessionId}
            assignments={assignments}
            communityAssignments={communityAssignments}
            roles={DEFAULT_ROLES}
          />
        </div>

        {/* Middle Column: Full Active Session Card */}
        <div className="lg:col-span-6">
          {activeSession && (
            <SessionCard
              key={activeSession.session_id}
              session={activeSession}
              assignments={assignments}
              communityAssignments={communityAssignments}
              roles={DEFAULT_ROLES}
              onOpenSelectModal={handleOpenSelectModal}
              onAssignCommunity={handleAssignCommunity}
              onRemoveAssignment={handleRemoveAssignment}
              wilayahOptions={[
                { value: 'Maria Ratu', label: 'Wilayah Maria Ratu' },
                { value: 'Maria Carmel', label: 'Wilayah Maria Carmel' },
                { value: 'Maria Immaculata', label: 'Wilayah Maria Immaculata' },
                { value: 'Brayat Minulya', label: 'Wilayah Brayat Minulya' },
                { value: 'Maria Assumpta', label: 'Wilayah Maria Assumpta' },
                { value: 'Maria Bunda Allah', label: 'Wilayah Maria Bunda Allah' },
                { value: 'Maria Cordis', label: 'Wilayah Maria Cordis' },
                { value: 'Maria Lourdes', label: 'Wilayah Maria Lourdes' },
                { value: 'Maria Mater Dei', label: 'Wilayah Maria Mater Dei' },
                { value: 'Maria Mater Dolorosa', label: 'Wilayah Maria Mater Dolorosa' },
                { value: 'Maria Ratu Rosari', label: 'Wilayah Maria Ratu Rosari' },
                { value: 'Maria Tak Bernoda', label: 'Wilayah Maria Tak Bernoda' },
                { value: 'Grasia', label: 'Grasia (Khusus)' },
                { value: 'Luar Paroki', label: 'Luar Paroki (Khusus)' },
                { value: 'Becanbo', label: 'Becanbo (Khusus)' }
              ]}
              lingkunganOptions={[
                { value: 'TIMOTIUS', label: 'Lingkungan Timotius' },
                { value: 'TITUS', label: 'Lingkungan Titus' },
                { value: 'YOHANES', label: 'Lingkungan Yohanes' },
                { value: 'LUKAS', label: 'Lingkungan Lukas' },
                { value: 'AGNES', label: 'Lingkungan Agnes' },
                { value: 'MATEUS', label: 'Lingkungan Mateus' },
                { value: 'THOMAS AQUINO', label: 'Lingkungan Thomas Aquino' },
                { value: 'AGATHA', label: 'Lingkungan Agatha' },
                { value: 'PETRUS', label: 'Lingkungan Petrus' },
                { value: 'BONAVENTURA', label: 'Lingkungan Bonaventura' },
                { value: 'BERNADETA', label: 'Lingkungan Bernadeta' },
                { value: 'FRANSISKUS', label: 'Lingkungan Fransiskus' },
                { value: 'YUSUP', label: 'Lingkungan Yusup' },
                { value: 'ANTONIUS', label: 'Lingkungan Antonius' },
                { value: 'ANDREAS', label: 'Lingkungan Andreas' },
                { value: 'IGNATIUS', label: 'Lingkungan Ignatius' },
                { value: 'CAECILIA', label: 'Lingkungan Caecilia' },
                { value: 'BLASIUS', label: 'Lingkungan Blasius' },
                { value: 'STEFANUS', label: 'Lingkungan Stefanus' },
                { value: 'HYPOLITUS', label: 'Lingkungan Hypolitus' }
              ]}
            />
          )}
        </div>

        {/* Right Column: Status Kelengkapan Checklist */}
        <div className="lg:col-span-3">
          <StatusPanel
            sessions={sessions.map((s) => ({
              id: s.session_id,
              name: s.nama_khusus || (s.jenis_sesi === 'SABTU_SORE' ? 'Sabtu Sore' : s.jenis_sesi === 'MINGGU_PAGI' ? 'Minggu Pagi' : 'Minggu Sore'),
              time: s.jenis_sesi === 'MINGGU_PAGI' ? '08.00' : '17.00'
            }))}
