              nama_khusus: s.nama_khusus,
              tanggal_sesi: s.tanggal_sesi,
              status: 'DRAFT'
            }))
          );
          setAssignments([]);
          setCommunityAssignments([]);
        }}
      />
    </div>
  );
}
