command($statusPanelCode = @'
import { Card } from '../ui';
import type { SessionProgress, CommunityAssignment } from '../../types';

interface StatusPanelProps {
  sessions: {
    id: string;
    name: string;
    time: string;
  }[];
  progressMap: Record<string, SessionProgress[]>;
  communityAssignments?: CommunityAssignment[];
}

export default function StatusPanel({
  sessions,
  progressMap,
  communityAssignments = [],
}: StatusPanelProps) {
  // Total overall weekend progress
  let totalSlotsNeeded = 0;
  let totalSlotsFilled = 0;

  sessions.forEach((s) => {
    const pList = progressMap[s.id] || [];
    pList.forEach((p) => {
      totalSlotsNeeded += p.dibutuhkan;
      totalSlotsFilled += Math.min(p.terisi, p.dibutuhkan);
    });
    // Add choir requirement (1 choir needed per session)
    totalSlotsNeeded += 1;
    const hasChoir = communityAssignments.some(
      (c) => c.session_id === s.id && c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED'
    );
    if (hasChoir) totalSlotsFilled += 1;
  });

  const overallPercent = totalSlotsNeeded > 0 ? Math.round((totalSlotsFilled / totalSlotsNeeded) * 100) : 0;

  return (
    <Card className="sticky top-24 backdrop-blur-3xl bg-gradient-to-br from-[#1B2921]/95 to-[#101914]/95 border border-white/10 text-white shadow-2xl p-5 md:p-6 rounded-3xl relative overflow-hidden">
      {/* Glossy top edge */}
      <div className="absolute top-0 left-0 right-0 h-[1px] bg-gradient-to-r from-transparent via-accent/30 to-transparent" />

      {/* Header & Overall Progress Ring */}
      <div className="border-b border-white/10 pb-4 mb-5">
        <div className="flex justify-between items-center mb-3">
          <h3 className="font-display font-bold text-accent text-base tracking-wide flex items-center gap-2">
            <span>📋</span>
            <span>Status Kelengkapan</span>
          </h3>
          <span className="text-[11px] font-mono text-accent font-bold bg-accent/15 px-2.5 py-0.5 rounded-full border border-accent/20">
            {overallPercent}% Selesai
          </span>
        </div>

        {/* Global Progress Bar */}
        <div className="w-full bg-white/10 h-2 rounded-full overflow-hidden p-0.5">
          <div
            className="bg-gradient-to-r from-accent to-emerald-400 h-full rounded-full transition-all duration-500 shadow-sm"
            style={{ width: `${overallPercent}%` }}
          />
        </div>
        <div className="flex justify-between items-center text-[10px] text-white/50 mt-1.5 font-medium">
          <span>Total: {totalSlotsFilled} dari {totalSlotsNeeded} slot terisi</span>
          {overallPercent === 100 && (
            <span className="text-accent font-bold animate-pulse">🎉 Siap Finalisasi!</span>
          )}
        </div>
      </div>

      {/* Session-by-Session Checklist */}
      <div className="space-y-4">
        {sessions.map((session) => {
          const progressList = progressMap[session.id] || [];
          const individualRolesFilled = progressList.every((p) => p.status === 'TERPENUHI');

          // Check if Choir is assigned in this session
          const hasChoir = communityAssignments.some(
            (c) => c.session_id === session.id && c.jenis_penugasan === 'PADUAN_SUARA' && c.status !== 'REMOVED'
          );

          // Check if Tatib is assigned in this session
          const hasTatib = communityAssignments.some(
            (c) => c.session_id === session.id && c.jenis_penugasan === 'TATIB' && c.status !== 'REMOVED'
          );

          const allFilled = individualRolesFilled && hasChoir;

          return (
            <div
              key={session.id}
              className={`p-3.5 rounded-2xl transition-all border ${
                allFilled
                  ? 'bg-emerald-500/10 border-emerald-500/30 shadow-[0_0_20px_rgba(16,185,129,0.1)]'
                  : 'bg-white/5 border-white/5'
              }`}
            >
              <div className="flex justify-between items-center mb-2.5">
                <span className="font-bold text-xs text-white/90">{session.name}</span>
                {allFilled ? (
                  <span className="text-[10px] bg-emerald-500/20 text-emerald-300 font-bold px-2 py-0.5 rounded-full border border-emerald-500/30 flex items-center gap-1">
                    <span>✓</span> Lengkap
                  </span>
                ) : (
                  <span className="text-[10px] text-white/40 font-medium">
                    Belum Lengkap
                  </span>
                )}
              </div>

              <div className="space-y-1.5 pl-0.5">
                {/* Paduan Suara Item */}
                <div className="flex items-center justify-between text-xs transition-colors">
                  <div className="flex items-center gap-2">
                    <span className={hasChoir ? 'text-accent font-bold' : 'text-white/30'}>
                      {hasChoir ? '●' : '○'}
                    </span>
                    <span className={hasChoir ? 'text-white/90 font-medium' : 'text-white/50'}>
                      Paduan Suara
                    </span>
                  </div>
                  <span
                    className={`text-[11px] font-medium ${
                      hasChoir ? 'text-accent font-bold' : 'text-white/40'
                    }`}
                  >
                    {hasChoir ? 'Terisi' : 'Kosong'}
                  </span>
                </div>

                {/* Individual Liturgical Roles */}
                {progressList.map((p) => {
                  const isDone = p.status === 'TERPENUHI';
                  return (
                    <div
                      key={p.roleId}
                      className="flex items-center justify-between text-xs transition-colors"
                    >
                      <div className="flex items-center gap-2">
                        <span className={isDone ? 'text-accent font-bold' : 'text-white/30'}>
                          {isDone ? '●' : '○'}
                        </span>
                        <span className={isDone ? 'text-white/90 font-medium' : 'text-white/50'}>
                          {p.namaPeran}
                        </span>
                      </div>
                      <span
                        className={`text-[11px] font-mono ${
                          isDone ? 'text-accent font-bold' : 'text-white/40'
                        }`}
                      >
                        {p.terisi}/{p.dibutuhkan}
                      </span>
                    </div>
                  );
                })}

                {/* Tatib Item */}
                <div className="flex items-center justify-between text-xs transition-colors">
                  <div className="flex items-center gap-2">
                    <span className={hasTatib ? 'text-accent font-bold' : 'text-white/30'}>
                      {hasTatib ? '●' : '○'}
                    </span>
                    <span className={hasTatib ? 'text-white/90 font-medium' : 'text-white/50'}>
                      Tatib
                    </span>
                  </div>
                  <span
                    className={`text-[11px] font-medium ${
                      hasTatib ? 'text-accent font-bold' : 'text-white/40'
                    }`}
                  >
                    {hasTatib ? 'Terisi' : 'Kosong'}
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </Card>
  );
}
'@

